import{_ as a,c as t,o as r,a5 as i}from"./chunks/framework.CGpSd67a.js";const p=JSON.parse('{"title":"Warranty","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/warranty.md","filePath":"faq/warranty.md"}'),o={name:"faq/warranty.md"};function n(h,e,s,l,c,y){return r(),t("div",{"data-pagefind-body":!0},e[0]||(e[0]=[i('<h1 id="warranty" tabindex="-1">Warranty <a class="header-anchor" href="#warranty" aria-label="Permalink to &quot;Warranty&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#what-is-your-return-policy">What is your return policy? ​</a></li><li><a href="#is-there-a-warranty-on-the-devices">Is there a warranty on the devices? ​</a></li><li><a href="#what-if-there-s-a-problem-with-my-device">What if there’s a problem with my device? ​</a></li></ul></nav><h2 id="what-is-your-return-policy" tabindex="-1">What is your return policy? <a class="header-anchor" href="#what-is-your-return-policy" aria-label="Permalink to &quot;What is your return policy?&quot;">​</a></h2><p>We’re sure that you will love our devices, but should you find the device is not for you, you are free to return it at your own expense within 14 days of receipt for a full refund (minus postage).</p><p>If there is a manufacturing problem with the device we&#39;ll cover all postage costs.</p><p>For further details, please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us</a>.</p><h2 id="is-there-a-warranty-on-the-devices" tabindex="-1">Is there a warranty on the devices? <a class="header-anchor" href="#is-there-a-warranty-on-the-devices" aria-label="Permalink to &quot;Is there a warranty on the devices?&quot;">​</a></h2><p>Yes, all devices are covered with 3 years warranty, more information about our 3 year warranty can be <a href="https://lightbug.io/feature/3-year-warranty/" target="_blank" rel="noreferrer">found here</a>.</p><p>Please note that we do not accept warranty claims on batteries if they have not been properly stored.</p><p>More information see the below FAQ on &quot;How to maintain a healthy battery when storing/shelving trackers?&quot;.</p><h2 id="what-if-there-s-a-problem-with-my-device" tabindex="-1">What if there’s a problem with my device? <a class="header-anchor" href="#what-if-there-s-a-problem-with-my-device" aria-label="Permalink to &quot;What if there’s a problem with my device?&quot;">​</a></h2><p>Please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us</a> and we’ll try our best to resolve the issue.</p><p>Each tracker comes with 3 years warranty against manufacturing defects.</p><h1 id="how-to-maintain-a-healthy-battery-when-storing-shelving-trackers" tabindex="-1">How to maintain a healthy battery when storing/shelving trackers? <a class="header-anchor" href="#how-to-maintain-a-healthy-battery-when-storing-shelving-trackers" aria-label="Permalink to &quot;How to maintain a healthy battery when storing/shelving trackers?&quot;">​</a></h1><p>If you are planning on not using a tracker for a while, please ensure that you fully charge the tracker before deactivating it.</p><p>All our rechargeable trackers contain lithium ion batteries.</p><p>Storing depleted batteries causes their capacity to deteriorate and will void any warranty claims relating to low battery capacity arising from improper storage.</p>',17)]))}const d=a(o,[["render",n]]);export{p as __pageData,d as default};
